import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import {
    parseFormData,
    setFormData,
    VlCheckboxComponent,
    VlDatepickerComponent,
    VlFormLabelComponent,
    VlInputFieldComponent,
    VlRadioComponent,
    VlRadioGroupComponent,
    VlSelectComponent,
    VlSelectRichComponent,
    VlUploadComponent,
} from '@domg-wc/components/form';

registerWebComponents([
    VlFormLabelComponent,
    VlInputFieldComponent,
    VlSelectComponent,
    VlSelectRichComponent,
    VlCheckboxComponent,
    VlRadioGroupComponent,
    VlRadioComponent,
    VlDatepickerComponent,
    VlUploadComponent,
    VlButtonComponent,
]);

document.querySelector('#hobbies').options = [
    { label: 'Padel', value: 'padel' },
    { label: 'Dans', value: 'dans' },
    { label: 'Drummen', value: 'drummen' },
    { label: 'Zwemmen', value: 'zwemmen' },
    { label: 'Boardgames', value: 'boardgames' },
    { label: 'Fietsen', value: 'fietsen' },
    { label: 'Cocktails', value: 'cocktails' },
];

const form = document.querySelector('#form');
const output = document.querySelector('#form-data');

// setFormData neemt hetzelfde formaat als wat parseFormData teruggeeft: een array voor velden met meerdere
// waarden, File-objecten voor vl-upload, en 'today' voor de datum van vandaag.
document.querySelector('#stel-in').addEventListener('click', () => {
    setFormData(form, {
        naam: 'Dehbi',
        geboorteplaats: 'knokke-heist',
        hobbies: ['drummen', 'dans'],
        betrokkenheid: ['plannende-overheid', 'hogere-overheid'],
        vervoer: 'zee',
        startDate: 'today',
        file: [
            new File(['Hallo, world!'], 'dossier.txt', { type: 'text/plain' }),
            new File(['Konichua, world!'], 'aanbeveling.txt', { type: 'text/plain' }),
        ],
    });
});

// parseFormData geeft één waarde per veld, en een array voor een veld met multiple of met een naam die
// meerdere keren voorkomt (hier hobbies en betrokkenheid).
form.addEventListener('submit', (event) => {
    event.preventDefault();
    const data = parseFormData(form);
    console.log(data);
    output.textContent = JSON.stringify(data, null, 2);
    output.hidden = false;
});
form.addEventListener('reset', () => {
    output.textContent = '';
    output.hidden = true;
});
